<script lang="ts" module>import type{Snippet}from'svelte';import type{RxColor}from'$lib/registry/lib/color';export interface PopupProps{open?:boolean;transition?:'zoom'|'bounce'|'flip'|'slide-up'|'fade';color?:RxColor;title?:string|Snippet;fullscreen?:boolean;preventClose?:boolean;footer?:Snippet;children:Snippet;trigger?:Snippet;onOpenChange?:(open:boolean)=>void}</script>
<script lang="ts">import * as Dialog from '$lib/components/ui/dialog';import{styleColor}from'$lib/registry/lib/color';let{open=$bindable(false),transition='zoom',color,title,fullscreen=false,preventClose=false,footer,children,trigger,onOpenChange}:PopupProps=$props();function changed(value:boolean){open=value;onOpenChange?.(value)}function prevent(event:Event){if(preventClose)event.preventDefault()}</script>
<Dialog.Root bind:open onOpenChange={changed}>{#if trigger}<Dialog.Trigger>{@render trigger()}</Dialog.Trigger>{/if}<Dialog.Content class={`rx-popup${fullscreen?' rx-popup--fullscreen':''}`} data-transition={transition} style={styleColor(color)??'--rx-color:var(--rx-primary)'} onEscapeKeydown={prevent} onInteractOutside={prevent}>{#if title}<Dialog.Header>{#if typeof title==='string'}<Dialog.Title>{title}</Dialog.Title>{:else}<Dialog.Title>{@render title()}</Dialog.Title>{/if}</Dialog.Header>{/if}<div class="rx-popup__body">{@render children()}</div>{#if footer}<Dialog.Footer>{@render footer()}</Dialog.Footer>{/if}</Dialog.Content></Dialog.Root>
<style>:global(.rx-popup){width:min(92vw,34rem);max-width:none;border:0;border-top:4px solid rgb(var(--rx-color));border-radius:calc(var(--rx-radius)*1.5);background:rgb(var(--rx-background));color:rgb(var(--rx-text));box-shadow:0 24px 70px rgb(var(--rx-dark)/.25)}:global(.rx-popup[data-state=open][data-transition=zoom]){animation:rx-popup-zoom .28s var(--rx-ease)}:global(.rx-popup[data-state=open][data-transition=bounce]){animation:rx-popup-bounce .42s cubic-bezier(.34,1.56,.64,1)}:global(.rx-popup[data-state=open][data-transition=flip]){animation:rx-popup-flip .36s var(--rx-ease);transform-origin:top}:global(.rx-popup[data-state=open][data-transition=slide-up]){animation:rx-popup-up .3s var(--rx-ease)}:global(.rx-popup[data-state=open][data-transition=fade]){animation:rx-popup-fade .2s linear}:global(.rx-popup--fullscreen){width:calc(100vw - 2rem);height:calc(100vh - 2rem)}.rx-popup__body{padding:.5rem 0}@keyframes rx-popup-zoom{from{opacity:0;transform:scale(.82)}}@keyframes rx-popup-bounce{from{opacity:0;transform:scale(.72)}60%{transform:scale(1.035)}}@keyframes rx-popup-flip{from{opacity:0;transform:perspective(800px) rotateX(-55deg)}}@keyframes rx-popup-up{from{opacity:0;transform:translateY(2rem)}}@keyframes rx-popup-fade{from{opacity:0}}@media(prefers-reduced-motion:reduce){:global(.rx-popup){animation:rx-popup-fade .01ms linear!important}}</style>
